INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 27, 'theory', 'Quiz: workers and PWAs');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 0, 'What cannot be passed to a worker with postMessage?', '["A date", "A Map and a Set", "A byte array", "A function or a DOM element"]', 3, 'Structured cloning can''t handle functions or page elements; dates, collections and circular references are supported.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 1, 'What does the transfer list do in postMessage?', '["Transfers ownership of the buffer: it becomes empty for the sender", "Copies the buffer faster", "Compresses the data", "Encrypts the message"]', 0, 'Transfer doesn''t copy memory; it hands the buffer over to another thread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 2, 'Why might a new Service Worker version stay in the waiting state?', '["There is an error in the code", "There is no internet", "The old version still controls open tabs", "The quota is used up"]', 2, 'While tabs are controlled by the old version, the new one waits; skipWaiting speeds up the switch but can mix versions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 3, 'Which strategy suits files with a hash in the name that never change?', '["Network Only", "Cache First", "Network First", "Always refresh"]', 1, 'If the name determines the content, it is safer and faster to always take it from the cache.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 27, 4, 'Why are old caches deleted during activate?', '["To free space and avoid mixing file versions", "To update the manifest", "To enable HTTPS", "The browser does this by itself"]', 0, 'The cache name includes the version; without cleanup, outdated stores pile up on disk.');
